<?php
$q=trim((string)($_GET['q']??''));$hasBank=$PCC->tableExists('play_stats');$char=$PCC->tableExists('rp_characters');$joins=($hasBank?' LEFT JOIN play_stats ps ON ps.id=u.id':'').($char?' LEFT JOIN rp_characters c ON c.user_id=u.id':'');$cols='u.id,u.username,u.look,u.online,u.credits'.($hasBank?',COALESCE(ps.bank,0) bank':',0 bank').($char?',c.first_name,c.last_name,c.citizen_id':',NULL first_name,NULL last_name,NULL citizen_id');$where='1=1';$types='';$params=array();if($q!==''){$like='%'.mb_substr($q,0,64).'%';$bits=array('u.username LIKE ?','CAST(u.id AS CHAR)=?');$types='ss';$params=array($like,$q);if($char){$bits[]='c.citizen_id LIKE ?';$bits[]="CONCAT(COALESCE(c.first_name,''),' ',COALESCE(c.last_name,'')) LIKE ?";$types.='ss';$params[]=$like;$params[]=$like;}$where='('.implode(' OR ',$bits).')';}$rows=$DB->PreparedAll('SELECT '.$cols.' FROM users u'.$joins.' WHERE '.$where.' ORDER BY (u.credits'.($hasBank?'+COALESCE(ps.bank,0)':'').') DESC LIMIT 500',$types,$params);$cash=$DB->PreparedRow('SELECT COALESCE(SUM(credits),0) v FROM users');$bank=$hasBank?$DB->PreparedRow('SELECT COALESCE(SUM(bank),0) v FROM play_stats'):array('v'=>0);
?>
<section class="pcc-balance-grid"><article><span>Cash total</span><strong><?php echo $number($cash['v']??0);?></strong><small>users.credits</small></article><article><span>Banque totale</span><strong><?php echo $number($bank['v']??0);?></strong><small><?php echo $hasBank?'play_stats.bank':'backend absent';?></small></article><article><span>Ledger économique</span><strong class="pcc-kpi-text">Non détecté</strong><small>Aucune table de transactions monétaires autoritaire n’a été identifiée.</small></article></section>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="economy"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Username, ID ou Citizen ID…"></div><button class="pcc-button secondary">Rechercher</button><span class="pcc-filter-count"><?php echo $number(count($rows));?> compte(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>Joueur</th><th>Nom RP</th><th>Citizen ID</th><th>Cash</th><th>Banque</th><th>Total</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$rp=trim((string)$r['first_name'].' '.(string)$r['last_name']);?><tr><td><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($r['look'],'s'));?>" alt=""><span><strong><?php echo $h($r['username']);?></strong><small class="pcc-subline">#<?php echo (int)$r['id'];?></small></span></div></td><td><?php echo $rp!==''?$h($rp):'—';?></td><td><code><?php echo $r['citizen_id']?$h($r['citizen_id']):'—';?></code></td><td><strong><?php echo $number($r['credits']);?></strong></td><td><?php echo $number($r['bank']);?></td><td><?php echo $number((int)$r['credits']+(int)$r['bank']);?></td><td><span class="pcc-badge <?php echo (int)$r['online']===1?'success':'';?>"><?php echo (int)$r['online']===1?'EN LIGNE':'HORS LIGNE';?></span></td><td><a class="pcc-button small secondary" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$r['id'];?>&tab=economy">Gérer</a></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="pcc-alert warning"><i class="fas fa-receipt"></i><div><strong>Historique Transactions non inventé</strong><p>Le core actuel possède des journaux métier pour Inventory V2, mais aucun ledger monétaire commun SALARY/TRANSFER/PAYMENT/SHOP n’a été identifié. La page n’invente donc pas de fausses transactions économiques.</p></div></section>
